import pytest
import requests
from datetime import datetime

# Test data for order creation
valid_order_data = {
    "id": 1,
    "petId": 1,
    "quantity": 1,
    "shipDate": datetime.now().isoformat(),
    "status": "placed",
    "complete": True
}

invalid_order_data = {
    "id": "invalid_id",
    "petId": 1,
    "quantity": 1,
    "shipDate": datetime.now().isoformat(),
    "status": "placed",
    "complete": True
}

@pytest.mark.parametrize("order_data, expected_status", [
    (valid_order_data, 200),
    (invalid_order_data, 400)
])
def test_place_order(api_client, valid_api_key, schema_validator, order_data, expected_status):
    """Test placing an order with valid and invalid data"""
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {valid_api_key}'
    }
    response = api_client.make_request(
        endpoint='v2/store/order',
        method='POST',
        headers=headers,
        params=order_data
    )
    assert response.status_code == expected_status
    if response.status_code == 200:
        assert schema_validator.validate_schema_order(response.json())

def test_place_order_missing_auth(api_client):
    """Test placing an order without authentication"""
    response = api_client.make_request(
        endpoint='v2/store/order',
        method='POST',
        params=valid_order_data
    )
    assert response.status_code == 401

def test_place_order_invalid_auth(api_client, invalid_api_key):
    """Test placing an order with invalid authentication"""
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {invalid_api_key}'
    }
    response = api_client.make_request(
        endpoint='v2/store/order',
        method='POST',
        headers=headers,
        params=valid_order_data
    )
    assert response.status_code == 401
